const { useEffect, useRef, useState } = React;

const AXES = [
  { value: "block", note: "沿块轴（垂直）滚动，进度随文章推进" },
  { value: "inline", note: "文章没有横向可滚动距离，时间轴 inactive，进度条停在起点" },
];
const SECTIONS = ["引言", "背景", "原理", "实践", "总结"];
const LINES = ["w-full", "w-11/12", "w-full", "w-4/5", "w-full", "w-3/5"];

const KIT_STYLE = `
  @scope {
    .cb-reading-progress {
      transform-origin: left;
      transform: scaleX(0);
      animation: cb-sda-progress linear both;
    }
  }
  @keyframes cb-sda-progress {
    to { transform: scaleX(1); }
  }
`;

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
    {children}
  </code>
);

const Choice = ({ active, onClick, children }) => (
  <button
    type="button"
    aria-pressed={active}
    onClick={onClick}
    className={`cursor-pointer rounded-tau-sm border px-2.5 py-1 font-tau-mono text-tau-sm transition-colors ${
      active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
    }`}
  >
    {children}
  </button>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

const Component = () => {
  const scrollerRef = useRef(null);
  const [axis, setAxis] = useState("block");
  const [metrics, setMetrics] = useState({ position: 0, range: 0 });

  // 只为读数测量滚动位置；进度条本身完全由 CSS 时间轴驱动
  useEffect(() => {
    const scroller = scrollerRef.current;
    const measure = () =>
      setMetrics(
        axis === "block"
          ? { position: scroller.scrollTop, range: scroller.scrollHeight - scroller.clientHeight }
          : { position: scroller.scrollLeft, range: scroller.scrollWidth - scroller.clientWidth },
      );
    measure();
    scroller.addEventListener("scroll", measure, { passive: true });
    const observer = new ResizeObserver(measure);
    observer.observe(scroller);
    return () => {
      scroller.removeEventListener("scroll", measure);
      observer.disconnect();
    };
  }, [axis]);

  const active = metrics.range > 0;
  const progress = active ? metrics.position / metrics.range : 0;
  const timeline = `scroll(nearest ${axis})`;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{KIT_STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div ref={scrollerRef} className="h-[260px] min-w-0 overflow-y-auto rounded-tau-md border border-line-1">
          <div className="sticky top-0 z-10 h-1 bg-hover">
            <div className="cb-reading-progress h-full bg-accent" style={{ animationTimeline: timeline }} />
          </div>
          <div className="flex flex-col gap-6 px-5 py-4">
            {SECTIONS.map((title, index) => (
              <section key={title} className="flex flex-col gap-2.5">
                <div className="text-tau-body text-ink-1">
                  {index + 1}. {title}
                </div>
                {LINES.map((width, line) => (
                  <div key={line} className={`h-2 rounded-full bg-hover ${width}`} />
                ))}
              </section>
            ))}
          </div>
        </div>
        <div className="flex min-w-0 flex-col gap-3">
          <div className="flex items-baseline gap-2">
            <span className="font-tau-mono text-tau-title text-ink-1">{Math.round(progress * 100)}%</span>
            <span className="text-tau-meta text-ink-3">{active ? "阅读进度" : "时间轴 inactive"}</span>
          </div>
          <Readout
            rows={[
              [axis === "block" ? "scrollTop" : "scrollLeft", `${Math.round(metrics.position)}px`],
              ["可滚动距离", `${Math.max(0, Math.round(metrics.range))}px`],
              ["进度", active ? `${Math.round(metrics.position)} / ${Math.round(metrics.range)}` : "无可滚动距离"],
            ]}
          />
          <p className="m-0 text-tau-meta text-ink-3">{AXES.find(item => item.value === axis).note}</p>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-tau-sm text-ink-3">滚动轴</span>
        {AXES.map(item => (
          <Choice key={item.value} active={axis === item.value} onClick={() => setAxis(item.value)}>
            {item.value}
          </Choice>
        ))}
        <span className="ml-auto">
          <Chip>animation-timeline: {timeline}</Chip>
        </span>
      </div>
    </div>
  );
};

