const { useEffect, useRef, useState } = React;

const PHOTO =
  "http://blog-hostimaging.oss-cn-beijing.aliyuncs.com/wallhaven-nr1vg1_19bf2bc3-5441-405b-bc81-480c62499c69.webp";
const VIEWPORT = 280;
// 背景高 150%，位移到 -33% 时底边恰好与视口底边对齐，再往上就会露出空白
const BG_SCALE = 1.5;
const CARDS = [
  { title: "前景", text: "卡片随滚动正常移动" },
  { title: "背景", text: "图片只移动了一小段距离" },
  { title: "速度差", text: "两层的位移差营造出纵深感" },
];

const KIT_STYLE = `
  @scope {
    .cb-parallax-bg {
      animation: cb-sda-parallax linear both;
      animation-timeline: scroll(nearest block);
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
  @keyframes cb-sda-parallax {
    from { transform: translateY(0); }
    to { transform: translateY(var(--cb-shift)); }
  }
`;

const shiftText = value => (value === 0 ? "0" : `-${value}%`);

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
    {children}
  </code>
);

const Slider = ({ label, value, min, max, onChange, format }) => (
  <label className="flex min-w-[220px] flex-1 items-center gap-3">
    <span className="shrink-0 text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{format(value)}</span>
  </label>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

const Component = () => {
  const scrollerRef = useRef(null);
  const [shift, setShift] = useState(33);
  const [metrics, setMetrics] = useState({ top: 0, range: 0 });

  useEffect(() => {
    const scroller = scrollerRef.current;
    const measure = () => setMetrics({ top: scroller.scrollTop, range: scroller.scrollHeight - scroller.clientHeight });
    measure();
    scroller.addEventListener("scroll", measure, { passive: true });
    const observer = new ResizeObserver(measure);
    observer.observe(scroller);
    return () => {
      scroller.removeEventListener("scroll", measure);
      observer.disconnect();
    };
  }, []);

  // 背景层贴在视口上（sticky），视口里看到的背景位移就是动画的 translateY
  const progress = metrics.range > 0 ? metrics.top / metrics.range : 0;
  const backgroundShift = progress * (shift / 100) * VIEWPORT * BG_SCALE;
  const ratio = metrics.range > 0 ? ((shift / 100) * VIEWPORT * BG_SCALE) / metrics.range : 0;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{KIT_STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          <div ref={scrollerRef} className="overflow-y-auto" style={{ height: VIEWPORT }}>
            {/* overflow: clip 不会形成滚动容器，图片的 scroll(nearest) 才能找到外层视口 */}
            <div
              className="pointer-events-none sticky top-0 overflow-clip"
              style={{ height: VIEWPORT, marginBottom: -VIEWPORT }}
            >
              <img
                src={PHOTO}
                alt=""
                className="cb-parallax-bg absolute inset-x-0 top-0 h-[150%] w-full object-cover"
                style={{ "--cb-shift": shiftText(shift) }}
              />
            </div>
            <div className="relative flex flex-col items-center gap-[120px] px-6 py-[150px]">
              {CARDS.map(card => (
                <div key={card.title} className="w-full max-w-[280px] rounded-tau-md bg-surface px-4 py-3 shadow-card">
                  <div className="text-tau-body text-ink-1">{card.title}</div>
                  <div className="text-tau-meta text-ink-3">{card.text}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
        <div className="flex min-w-0 flex-col gap-3">
          <div className="flex items-baseline gap-2">
            <span className="font-tau-mono text-tau-title text-ink-1">{ratio.toFixed(2)}×</span>
            <span className="text-tau-meta text-ink-3">背景相对内容的速度</span>
          </div>
          <Readout
            rows={[
              ["时间轴进度", `${Math.round(progress * 100)}%`],
              ["内容位移", `${Math.round(metrics.top)}px`],
              ["背景位移", `${Math.round(backgroundShift)}px`],
            ]}
          />
          <p className="m-0 text-tau-meta text-ink-3">
            {shift === 0 ? "背景不动，相当于固定背景。" : "两层同向移动，背景更慢，于是显得更远。"}
          </p>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <Slider label="背景终点" value={shift} min={0} max={33} onChange={setShift} format={shiftText} />
        <Chip>
          to {"{"} transform: translateY({shiftText(shift)}) {"}"}
        </Chip>
      </div>
    </div>
  );
};

