const { useEffect, useRef, useState } = React;

// 本块演示的命名范围（第一项为主范围）与默认元素尺寸
const RANGES = ["entry"];
const DEFAULT_SIZE = "short";

const VIEWPORT = 240;
const SIZES = [
  { value: "short", label: "元素比视口矮", height: 96 },
  { value: "tall", label: "元素比视口高", height: 340 },
];

// 各命名范围的起止位置（以 scrollTop 表示）。元素上方留了一屏空白，scrollTop = 0 时元素顶部恰好与视口底部重合
const rangeOf = (name, height) => {
  const tall = height > VIEWPORT;
  const top = VIEWPORT;
  const containStart = top - VIEWPORT + Math.min(height, VIEWPORT);
  const containEnd = top + Math.max(0, height - VIEWPORT);
  switch (name) {
    case "entry":
      return {
        start: top - VIEWPORT,
        end: containStart,
        from: "元素顶部 = 视口底部",
        to: tall ? "元素顶部 = 视口顶部" : "元素底部 = 视口底部",
      };
    case "exit":
      return {
        start: containEnd,
        end: top + height,
        from: tall ? "元素底部 = 视口底部" : "元素顶部 = 视口顶部",
        to: "元素底部 = 视口顶部",
      };
    case "contain":
      return {
        start: containStart,
        end: containEnd,
        from: tall ? "元素顶部 = 视口顶部" : "元素底部 = 视口底部",
        to: tall ? "元素底部 = 视口底部" : "元素顶部 = 视口顶部",
      };
    case "entry-crossing":
      return {
        start: top - VIEWPORT,
        end: top - VIEWPORT + height,
        from: "元素顶部 = 视口底部",
        to: "元素底部 = 视口底部",
      };
    case "exit-crossing":
      return { start: top, end: top + height, from: "元素顶部 = 视口顶部", to: "元素底部 = 视口顶部" };
    default:
      return { start: top - VIEWPORT, end: top + height, from: "元素顶部 = 视口底部", to: "元素底部 = 视口顶部" };
  }
};

const clamp = value => Math.min(1, Math.max(0, value));
const percent = value => `${Math.round(value * 100)}%`;
const BAR_TONES = ["bg-accent", "bg-tag-3"];

const KIT_STYLE = `
  @scope {
    .cb-subject { view-timeline: --cb-subject block; }
    .cb-meter {
      counter-reset: cb-sda var(--cb-sda-p);
      animation: cb-sda-meter linear both;
    }
    .cb-meter-fill {
      transform-origin: left;
      transform: scaleX(calc(var(--cb-sda-p) / 100));
    }
    .cb-meter-value::after { content: counter(cb-sda) "%"; }
  }
  @property --cb-sda-p {
    syntax: "<integer>";
    inherits: true;
    initial-value: 0;
  }
  @keyframes cb-sda-meter {
    from { --cb-sda-p: 0; }
    to { --cb-sda-p: 100; }
  }
`;

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
    {children}
  </code>
);

const Choice = ({ active, onClick, children }) => (
  <button
    type="button"
    aria-pressed={active}
    onClick={onClick}
    className={`cursor-pointer rounded-tau-sm border px-2.5 py-1 text-tau-sm transition-colors ${
      active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
    }`}
  >
    {children}
  </button>
);

// 由 CSS 时间轴驱动的进度条：数字是 @property 整数经 counter 显示，不经过 JS
const Meter = ({ label, style }) => (
  <div className="cb-meter flex items-center gap-2" style={style}>
    <span className="w-24 shrink-0 truncate font-tau-mono text-tau-tiny text-accent-text">{label}</span>
    <div className="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-surface">
      <div className="cb-meter-fill h-full rounded-full bg-accent" />
    </div>
    <span className="cb-meter-value w-9 shrink-0 text-right font-tau-mono text-tau-tiny text-accent-text" />
  </div>
);

const Edge = ({ children, className = "" }) => (
  <span className={`pointer-events-none absolute right-2 font-tau-mono text-tau-tiny text-ink-3 ${className}`}>
    {children}
  </span>
);

const Component = () => {
  const scrollerRef = useRef(null);
  const [size, setSize] = useState(DEFAULT_SIZE);
  const [scrollTop, setScrollTop] = useState(0);
  const height = SIZES.find(item => item.value === size).height;

  useEffect(() => {
    const scroller = scrollerRef.current;
    const onScroll = () => setScrollTop(scroller.scrollTop);
    scroller.addEventListener("scroll", onScroll, { passive: true });
    return () => scroller.removeEventListener("scroll", onScroll);
  }, []);

  const total = VIEWPORT + height;
  const coverAt = value => clamp(value / total);
  const ranges = RANGES.map(name => ({ name, ...rangeOf(name, height) }));
  const primary = ranges[0];
  const progressOf = range => clamp((scrollTop - range.start) / Math.max(1, range.end - range.start));
  const status = scrollTop < primary.start - 0.5 ? "未开始" : scrollTop > primary.end + 0.5 ? "已结束" : "进行中";
  // 时间轴图上始终保留 cover 作为整条视图时间轴的参照
  const rows = [
    ...(RANGES.includes("cover") ? [] : [{ name: "cover", start: 0, end: total, tone: "bg-press" }]),
    ...ranges.map((range, index) => ({ ...range, tone: BAR_TONES[index] })),
  ];
  const scrollTo = top => scrollerRef.current?.scrollTo({ top, behavior: "smooth" });

  return (
    <div className="@container flex flex-col gap-3">
      <style>{KIT_STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          <div ref={scrollerRef} className="overflow-y-auto" style={{ height: VIEWPORT }}>
            <div style={{ height: VIEWPORT }} className="flex items-end justify-center pb-3 text-tau-meta text-ink-3">
              向下滚动，让元素穿过视口
            </div>
            <div
              className="cb-subject mx-6 flex flex-col justify-between rounded-tau-md border border-accent bg-accent-soft px-3 py-1.5"
              style={{ height }}
            >
              <span className="font-tau-mono text-tau-tiny text-accent-text">元素顶部</span>
              <div className="flex flex-col gap-1.5">
                {ranges.map(range => (
                  <Meter
                    key={range.name}
                    label={range.name}
                    style={{ animationTimeline: "--cb-subject", animationRange: `${range.name} 0% ${range.name} 100%` }}
                  />
                ))}
              </div>
              <span className="font-tau-mono text-tau-tiny text-accent-text">元素底部</span>
            </div>
            <div style={{ height: VIEWPORT }} />
          </div>
          <Edge className="top-1">视口顶部</Edge>
          <Edge className="bottom-1">视口底部</Edge>
        </div>

        <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          <div className="flex items-center justify-between gap-2">
            <Chip>{primary.name}</Chip>
            <ui.Tag color={status === "进行中" ? "blue" : status === "已结束" ? "green" : "gray"}>{status}</ui.Tag>
          </div>
          <div className="flex items-baseline gap-2">
            <span className="font-tau-mono text-tau-title text-ink-1">{percent(progressOf(primary))}</span>
            <span className="text-tau-meta text-ink-3">{primary.name} 进度</span>
          </div>

          <div className="relative flex flex-col gap-1.5">
            {rows.map(row => (
              <div key={row.name} className="grid grid-cols-[104px_minmax(0,1fr)] items-center gap-2">
                <span className="truncate font-tau-mono text-tau-tiny text-ink-2">{row.name}</span>
                <div className="relative h-2 rounded-full bg-hover">
                  <div
                    className={`absolute inset-y-0 rounded-full ${row.tone}`}
                    style={{ left: percent(coverAt(row.start)), width: percent(coverAt(row.end) - coverAt(row.start)) }}
                  />
                </div>
              </div>
            ))}
            <div
              className="pointer-events-none absolute -inset-y-1 w-0.5 rounded-full bg-ink-1 transition-[left] duration-75"
              style={{ left: `calc(112px + (100% - 112px) * ${coverAt(scrollTop)})` }}
            />
          </div>
          <div className="flex justify-between pl-[112px] font-tau-mono text-tau-tiny text-ink-3">
            <span>cover 0%</span>
            <span>cover 100%</span>
          </div>

          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
            {[
              ["起点", primary.from, scrollTop >= primary.start - 0.5],
              ["终点", primary.to, scrollTop >= primary.end - 0.5],
            ].map(([label, text, reached]) => (
              <React.Fragment key={label}>
                <dt className="flex items-center gap-1.5 text-ink-3">
                  {reached ? (
                    <icons.CircleCheck className="size-3.5 text-accent" />
                  ) : (
                    <icons.Circle className="size-3.5" />
                  )}
                  {label}
                </dt>
                <dd className="m-0 min-w-0 text-ink-1">{text}</dd>
              </React.Fragment>
            ))}
            <dt className="text-ink-3">尺寸</dt>
            <dd className="m-0 font-tau-mono text-ink-1">
              元素 {height}px / 视口 {VIEWPORT}px
            </dd>
          </dl>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        {SIZES.map(item => (
          <Choice key={item.value} active={size === item.value} onClick={() => setSize(item.value)}>
            {item.label}
          </Choice>
        ))}
        <span className="ml-auto flex gap-1">
          <ui.Button variant="ghost" size="sm" icon={icons.ArrowUpToLine} onClick={() => scrollTo(primary.start)}>
            滚到起点
          </ui.Button>
          <ui.Button variant="ghost" size="sm" icon={icons.ArrowDownToLine} onClick={() => scrollTo(primary.end)}>
            滚到终点
          </ui.Button>
        </span>
      </div>
    </div>
  );
};

const { useEffect, useRef, useState } = React;

// 本块演示的命名范围（第一项为主范围）与默认元素尺寸
const RANGES = ["exit"];
const DEFAULT_SIZE = "short";

const VIEWPORT = 240;
const SIZES = [
  { value: "short", label: "元素比视口矮", height: 96 },
  { value: "tall", label: "元素比视口高", height: 340 },
];

// 各命名范围的起止位置（以 scrollTop 表示）。元素上方留了一屏空白，scrollTop = 0 时元素顶部恰好与视口底部重合
const rangeOf = (name, height) => {
  const tall = height > VIEWPORT;
  const top = VIEWPORT;
