const rangeOf = (name, height) => {
  const tall = height > VIEWPORT;
  const top = VIEWPORT;
  const containStart = top - VIEWPORT + Math.min(height, VIEWPORT);
  const containEnd = top + Math.max(0, height - VIEWPORT);
  switch (name) {
    case "entry":
      return {
        start: top - VIEWPORT,
        end: containStart,
        from: "元素顶部 = 视口底部",
