const { useRef, useState } = React;

const ITEMS = [
  { title: "极速性能", desc: "滚动进度由浏览器原生时间轴计算" },
  { title: "声明式语法", desc: "无需监听 scroll 事件或维护动画状态" },
  { title: "精确控制", desc: "通过 animation-range 定义动画生效区间" },
  { title: "视图驱动", desc: "元素根据自身在滚动容器中的位置产生动画" },
  { title: "滚动驱动", desc: "滚动位置可以直接映射为 CSS 动画进度" },
  { title: "原生支持", desc: "无需引入第三方滚动动画库" },
];
const VIEWPORT = 320;
const CARD = 72;
const PRESETS = [
  {
    value: "entry 0% cover 35%",
    start: ["entry", 0],
    end: ["cover", 35],
    note: "一露头就开始，越过 cover 35% 时完全显现",
  },
  {
    value: "entry 0% entry 100%",
    start: ["entry", 0],
    end: ["entry", 100],
    note: "只在进入阶段播放，卡片完全进入时结束",
  },
  {
    value: "cover 0% cover 50%",
    start: ["cover", 0],
    end: ["cover", 50],
    note: "播放区间拉长到时间轴的一半，显现更慢",
  },
  {
    value: "contain 0% contain 100%",
    start: ["contain", 0],
    end: ["contain", 100],
    note: "完全进入后才开始，卡片要走到视口顶部才显现完",
  },
];

// 把「范围名 + 百分比」换算到整条 cover 时间轴上的位置（卡片比视口矮）
const toCover = ([name, percent]) => {
  const p = percent / 100;
  const total = VIEWPORT + CARD;
  if (name === "entry") return (p * CARD) / total;
  if (name === "contain") return (CARD + p * (VIEWPORT - CARD)) / total;
  if (name === "exit") return (VIEWPORT + p * CARD) / total;
  return p;
};

const KIT_STYLE = `
  @scope {
    .cb-reveal {
      opacity: 0;
      transform: translateY(60px);
      counter-reset: cb-sda var(--cb-sda-p);
      animation: cb-sda-reveal linear both;
      animation-timeline: view();
    }
    .cb-reveal-value::after { content: counter(cb-sda) "%"; }
  }
  @property --cb-sda-p {
    syntax: "<integer>";
    inherits: true;
    initial-value: 0;
  }
  @keyframes cb-sda-reveal {
    to {
      opacity: 1;
      transform: translateY(0);
      --cb-sda-p: 100;
    }
  }
`;

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
    {children}
  </code>
);

const Choice = ({ active, onClick, children }) => (
  <button
    type="button"
    aria-pressed={active}
    onClick={onClick}
    className={`cursor-pointer rounded-tau-sm border px-2.5 py-1 font-tau-mono text-tau-sm transition-colors ${
      active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
    }`}
  >
    {children}
  </button>
);

const Component = () => {
  const scrollerRef = useRef(null);
  const [preset, setPreset] = useState(PRESETS[0].value);
  const current = PRESETS.find(item => item.value === preset);
  const from = toCover(current.start);
  const to = toCover(current.end);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{KIT_STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div
          ref={scrollerRef}
          className="min-w-0 overflow-y-auto rounded-tau-md border border-line-1 px-4"
          style={{ height: VIEWPORT }}
        >
          <div className="flex h-[240px] items-end justify-center pb-4 text-tau-meta text-ink-3">
            向下滚动，观察卡片依次进入视口
          </div>
          <div className="flex flex-col gap-3">
            {ITEMS.map((item, index) => (
              <div
                key={item.title}
                className="cb-reveal flex items-center gap-3 rounded-tau-md border border-line-1 bg-surface px-3 shadow-card"
                style={{ height: CARD, animationRange: preset }}
              >
                <span className="grid size-8 shrink-0 place-items-center rounded-full bg-accent-soft font-tau-mono text-tau-sm text-accent-text">
                  {index + 1}
                </span>
                <div className="flex min-w-0 flex-1 flex-col">
                  <span className="text-tau-body text-ink-1">{item.title}</span>
                  <span className="truncate text-tau-meta text-ink-3">{item.desc}</span>
                </div>
                <span className="cb-reveal-value shrink-0 rounded-full bg-hover px-1.5 font-tau-mono text-tau-tiny text-ink-2" />
              </div>
            ))}
          </div>
          <div className="h-[200px]" />
        </div>
        <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">动画区间在视图时间轴上的位置</span>
          <div className="relative h-2 rounded-full bg-hover">
            <div
              className="absolute inset-y-0 rounded-full bg-accent"
              style={{ left: `${from * 100}%`, width: `${(to - from) * 100}%` }}
            />
          </div>
          <div className="flex justify-between font-tau-mono text-tau-tiny text-ink-3">
            <span>cover 0%</span>
            <span>
              {Math.round(from * 100)}% → {Math.round(to * 100)}%
            </span>
            <span>cover 100%</span>
          </div>
          <p className="m-0 text-tau-meta text-ink-2">{current.note}</p>
          <p className="m-0 text-tau-meta text-ink-3">
            卡片右侧的百分比由同一条时间轴驱动，换算自卡片 {CARD}px、视口 {VIEWPORT}px。
          </p>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        {PRESETS.map(item => (
          <Choice key={item.value} active={preset === item.value} onClick={() => setPreset(item.value)}>
            {item.value}
          </Choice>
        ))}
        <ui.Button
          variant="ghost"
          size="sm"
          icon={icons.ArrowUpToLine}
          className="ml-auto"
          onClick={() => scrollerRef.current?.scrollTo({ top: 0, behavior: "smooth" })}
        >
          回到顶部
        </ui.Button>
      </div>
      <Chip>animation-range: {preset}</Chip>
    </div>
  );
};

