const { useRef, useState } = React;

const PHOTO =
  "http://blog-hostimaging.oss-cn-beijing.aliyuncs.com/wallhaven-nr1vg1_19bf2bc3-5441-405b-bc81-480c62499c69.webp";
const VIEWPORT = 340;
const PHOTO_HEIGHT = 200;
const PRESETS = [
  { value: "entry 10% cover 50%", start: ["entry", 10], end: ["cover", 50] },
  { value: "entry 0% entry 100%", start: ["entry", 0], end: ["entry", 100] },
  { value: "cover 0% cover 100%", start: ["cover", 0], end: ["cover", 100] },
];
const NOTES = [
  { title: "视觉层次感", text: "图片的缩放和透明度直接由视图进度时间轴驱动。" },
  { title: "声明式实现", text: "无需监听 scroll 事件，也无需在组件状态中保存动画进度。" },
];

// 把「范围名 + 百分比」换算到整条 cover 时间轴上的位置（图片比视口矮）
const toCover = ([name, percent]) => {
  const p = percent / 100;
  const total = VIEWPORT + PHOTO_HEIGHT;
  if (name === "entry") return (p * PHOTO_HEIGHT) / total;
  if (name === "contain") return (PHOTO_HEIGHT + p * (VIEWPORT - PHOTO_HEIGHT)) / total;
  return p;
};

const KIT_STYLE = `
  @scope {
    .cb-photo {
      scale: var(--cb-scale);
      opacity: var(--cb-opacity);
      counter-reset: cb-sda var(--cb-sda-p);
      animation: cb-sda-photo linear both;
      animation-timeline: view();
    }
    .cb-photo-value::after { content: counter(cb-sda) "%"; }
    .cb-range { accent-color: var(--tau-accent); }
  }
  @property --cb-sda-p {
    syntax: "<integer>";
    inherits: true;
    initial-value: 0;
  }
  @keyframes cb-sda-photo {
    to {
      scale: 1;
      opacity: 1;
      --cb-sda-p: 100;
    }
  }
`;

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
    {children}
  </code>
);

const Choice = ({ active, onClick, children }) => (
  <button
    type="button"
    aria-pressed={active}
    onClick={onClick}
    className={`cursor-pointer rounded-tau-sm border px-2.5 py-1 font-tau-mono text-tau-sm transition-colors ${
      active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
    }`}
  >
    {children}
  </button>
);

const Slider = ({ label, value, min, max, step, onChange }) => (
  <label className="flex min-w-[200px] flex-1 items-center gap-3">
    <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-10 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{value.toFixed(2)}</span>
  </label>
);

const Component = () => {
  const scrollerRef = useRef(null);
  const [preset, setPreset] = useState(PRESETS[0].value);
  const [scale, setScale] = useState(0.85);
  const [opacity, setOpacity] = useState(0.5);
  const current = PRESETS.find(item => item.value === preset);
  const from = toCover(current.start);
  const to = toCover(current.end);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{KIT_STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div
          ref={scrollerRef}
          className="min-w-0 overflow-y-auto rounded-tau-md border border-line-1 px-4"
          style={{ height: VIEWPORT }}
        >
          <div className="flex h-[260px] flex-col items-center justify-end gap-1 pb-4 text-tau-meta text-ink-3">
            向下滚动，图片从视口底部进入并逐渐放大
            <icons.ArrowDown className="size-4" />
          </div>
          <div
            className="cb-photo relative overflow-hidden rounded-tau-md"
            style={{ height: PHOTO_HEIGHT, animationRange: preset, "--cb-scale": scale, "--cb-opacity": opacity }}
          >
            <img src={PHOTO} alt="" className="size-full object-cover" />
            <span className="cb-photo-value absolute left-2 top-2 rounded-full bg-surface px-1.5 font-tau-mono text-tau-tiny text-ink-2 shadow-card" />
          </div>
          <div className="flex flex-col gap-3 py-4">
            {NOTES.map(note => (
              <div key={note.title} className="rounded-tau-md border border-line-1 bg-surface px-3 py-2.5">
                <div className="text-tau-body text-ink-1">{note.title}</div>
                <div className="text-tau-meta text-ink-3">{note.text}</div>
              </div>
            ))}
          </div>
          <div className="h-[160px]" />
        </div>
        <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">动画区间在视图时间轴上的位置</span>
          <div className="relative h-2 rounded-full bg-hover">
            <div
              className="absolute inset-y-0 rounded-full bg-accent"
              style={{ left: `${from * 100}%`, width: `${(to - from) * 100}%` }}
            />
          </div>
          <div className="flex justify-between font-tau-mono text-tau-tiny text-ink-3">
            <span>cover 0%</span>
            <span>
              {Math.round(from * 100)}% → {Math.round(to * 100)}%
            </span>
            <span>cover 100%</span>
          </div>
          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
            <dt className="text-ink-3">区间前</dt>
            <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">
              scale: {scale.toFixed(2)}; opacity: {opacity.toFixed(2)}
            </dd>
            <dt className="text-ink-3">区间后</dt>
            <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">scale: 1; opacity: 1</dd>
          </dl>
          <p className="m-0 text-tau-meta text-ink-3">图片左上角的百分比是动画进度，由同一条视图时间轴驱动。</p>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <Slider label="scale" value={scale} min={0.5} max={1} step={0.05} onChange={setScale} />
        <Slider label="opacity" value={opacity} min={0} max={1} step={0.05} onChange={setOpacity} />
      </div>
      <div className="flex flex-wrap items-center gap-2">
        {PRESETS.map(item => (
          <Choice key={item.value} active={preset === item.value} onClick={() => setPreset(item.value)}>
            {item.value}
          </Choice>
        ))}
        <ui.Button
          variant="ghost"
          size="sm"
          icon={icons.ArrowUpToLine}
          className="ml-auto"
          onClick={() => scrollerRef.current?.scrollTo({ top: 0, behavior: "smooth" })}
        >
          回到顶部
        </ui.Button>
      </div>
      <Chip>animation-range: {preset}</Chip>
    </div>
  );
};

