content.content:
const { useEffect, useRef, useState } = React;

const CARDS = [
  { title: "极速性能", desc: "浏览器原生时间轴" },
  { title: "声明式语法", desc: "纯 CSS 驱动" },
  { title: "精确控制", desc: "range 定义区间" },
  { title: "视图驱动", desc: "view() 时间轴" },
  { title: "滚动驱动", desc: "scroll() 时间轴" },
  { title: "原生支持", desc: "无需第三方库" },
];
const CARD_WIDTH = 160;
const GAP = 16;

const KIT_STYLE = `
  @scope {
    .cb-carousel { scroll-snap-type: x mandatory; scrollbar-width: thin; }
    .cb-carousel[data-snap="off"] { scroll-snap-type: none; }
    .cb-carousel-card {
      scroll-snap-align: center;
      counter-reset: cb-sda var(--cb-sda-p);
      animation: cb-sda-focus linear both;
      animation-timeline: view(inline);
      animation-range: entry 0% exit 100%;
    }
    .cb-carousel-value::after { content: counter(cb-sda) "%"; }
  }
  @property --cb-sda-p {
    syntax: "<integer>";
    inherits: true;
    initial-value: 0;
  }
  @keyframes cb-sda-focus {
    0% { scale: 0.8; opacity: 0.45; border-color: var(--tau-line-1); --cb-sda-p: 0; }
    25%, 75% { scale: 1; opacity: 1; border-color: var(--tau-accent); }
    100% { scale: 0.8; opacity: 0.45; border-color: var(--tau-line-1); --cb-sda-p: 100; }
  }
`;

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
    {children}
  </code>
);

const Component = () => {
  const trackRef = useRef(null);
  const [snap, setSnap] = useState(true);
  const [centered, setCentered] = useState(0);

  // 只为读数找出最靠近中线的卡片；缩放与高亮完全由 CSS 视图时间轴驱动
  useEffect(() => {
    const track = trackRef.current;
    const onScroll = () => setCentered(Math.round(track.scrollLeft / (CARD_WIDTH + GAP)));
    track.addEventListener("scroll", onScroll, { passive: true });
    return () => track.removeEventListener("scroll", onScroll);
  }, []);

  const go = step => {
    const next = Math.min(CARDS.length - 1, Math.max(0, centered + step));
    trackRef.current?.scrollTo({ left: next * (CARD_WIDTH + GAP), behavior: "smooth" });
  };

  return (
    <div className="flex flex-col gap-3">
      <style>{KIT_STYLE}</style>
      <div className="relative rounded-tau-md border border-line-1">
        <div
          ref={trackRef}
          data-snap={snap ? "on" : "off"}
          className="cb-carousel flex overflow-x-auto py-6"
          style={{ gap: GAP, paddingInline: `calc(50% - ${CARD_WIDTH / 2}px)` }}
        >
          {CARDS.map((card, index) => (
            <div
              key={card.title}
              className="cb-carousel-card flex shrink-0 select-none flex-col items-center gap-2 rounded-tau-md border-2 border-line-1 bg-surface px-4 py-5 shadow-card"
              style={{ width: CARD_WIDTH }}
            >
              <span className="grid size-10 place-items-center rounded-full bg-accent-soft font-tau-mono text-tau-body text-accent-text">
                {index + 1}
              </span>
              <span className="text-tau-body text-ink-1">{card.title}</span>
              <span className="text-tau-meta text-ink-3">{card.desc}</span>
              <span className="cb-carousel-value rounded-full bg-hover px-1.5 font-tau-mono text-tau-tiny text-ink-2" />
            </div>
          ))}
        </div>
        <div className="pointer-events-none absolute inset-y-2 left-1/2 w-px border-l border-dashed border-line-1" />
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.IconButton aria-label="上一张" onClick={() => go(-1)}>
          <icons.ChevronLeft className="size-4" />
        </ui.IconButton>
        <ui.IconButton aria-label="下一张" onClick={() => go(1)}>
          <icons.ChevronRight className="size-4" />
        </ui.IconButton>
        <span className="font-tau-mono text-tau-meta text-ink-3">
          居中：第 {centered + 1} 张 / 共 {CARDS.length} 张
        </span>
        <span className="ml-auto">
          <ui.Switch checked={snap} onCheckedChange={setSnap} label="滚动吸附" />
        </span>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <Chip>animation-timeline: view(inline)</Chip>
        <Chip>animation-range: entry 0% exit 100%</Chip>
        <Chip>scroll-snap-type: {snap ? "x mandatory" : "none"}</Chip>
      </div>
      <p className="m-0 text-tau-meta text-ink-3">卡片经过中线时进度为 50%，关键帧 25% 到 75% 之间保持放大高亮。</p>
    </div>
  );
};

