content.content:
const { useEffect, useRef, useState } = React;

const VIEWPORT = 320;
// 每个元素都引用 --mission-scroll，只是关键帧与 animation-range 不同
const ACTORS = [
  { label: "顶部进度条", range: [0, 100] },
  { label: "左侧指标", range: [0, 30] },
  { label: "右侧指标", range: [20, 50] },
  { label: "中心徽章", range: [30, 60] },
  { label: "标签 1", range: [45, 70] },
  { label: "标签 2", range: [55, 80] },
  { label: "标签 3", range: [65, 90] },
];
const rangeOf = label => {
  const [start, end] = ACTORS.find(actor => actor.label === label).range;
  return `${start}% ${end}%`;
};
const CHIPS = [
  { label: "性能优化", actor: "标签 1", className: "bg-tag-1-soft text-tag-1" },
  { label: "线程隔离", actor: "标签 2", className: "bg-tag-2-soft text-tag-2" },
  { label: "声明式动画", actor: "标签 3", className: "bg-tag-3-soft text-tag-3" },
];

const KIT_STYLE = `
  @scope {
    .cb-mission-scroller { scroll-timeline: --mission-scroll block; }
    .cb-mission-progress {
      transform-origin: left;
      transform: scaleX(0);
      animation: cb-sda-mission-fill linear both;
      animation-timeline: --mission-scroll;
    }
    .cb-mission-left { animation: cb-sda-mission-left linear both; animation-timeline: --mission-scroll; }
    .cb-mission-right { animation: cb-sda-mission-right linear both; animation-timeline: --mission-scroll; }
    .cb-mission-badge { animation: cb-sda-mission-badge linear both; animation-timeline: --mission-scroll; }
    .cb-mission-chip { animation: cb-sda-mission-chip linear both; animation-timeline: --mission-scroll; }
    .cb-mission-total {
      counter-reset: cb-sda var(--cb-sda-p);
      animation: cb-sda-meter linear both;
      animation-timeline: --mission-scroll;
    }
    .cb-mission-total-value::after { content: counter(cb-sda) "%"; }
  }
  @property --cb-sda-p {
    syntax: "<integer>";
    inherits: true;
    initial-value: 0;
  }
  @keyframes cb-sda-meter {
    from { --cb-sda-p: 0; }
    to { --cb-sda-p: 100; }
  }
  @keyframes cb-sda-mission-fill {
    to { transform: scaleX(1); }
  }
  @keyframes cb-sda-mission-left {
    from { opacity: 0; transform: translateX(-60px); }
    to { opacity: 1; transform: translateX(0); }
  }
  @keyframes cb-sda-mission-right {
    from { opacity: 0; transform: translateX(60px); }
    to { opacity: 1; transform: translateX(0); }
  }
  @keyframes cb-sda-mission-badge {
    from { opacity: 0; transform: scale(0.5) rotate(-90deg); }
    to { opacity: 1; transform: scale(1) rotate(0deg); }
  }
  @keyframes cb-sda-mission-chip {
    from { opacity: 0; transform: translateY(24px); }
    to { opacity: 1; transform: translateY(0); }
  }
`;

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
    {children}
  </code>
);

const Stat = ({ className, style, value, label }) => (
  <div
    className={`flex flex-col rounded-tau-md border border-line-1 bg-surface px-3 py-2 shadow-card ${className}`}
    style={style}
  >
    <span className="font-tau-mono text-tau-title text-ink-1">{value}</span>
    <span className="text-tau-meta text-ink-3">{label}</span>
  </div>
);

const Component = () => {
  const scrollerRef = useRef(null);
  const [progress, setProgress] = useState(0);

  // 只为右侧分镜表的指针读出滚动进度；舞台上的动画全部由命名时间轴驱动
  useEffect(() => {
    const scroller = scrollerRef.current;
    const onScroll = () => {
      const range = scroller.scrollHeight - scroller.clientHeight;
      setProgress(range > 0 ? (scroller.scrollTop / range) * 100 : 0);
    };
    scroller.addEventListener("scroll", onScroll, { passive: true });
    return () => scroller.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{KIT_STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          <div ref={scrollerRef} className="cb-mission-scroller overflow-y-auto" style={{ height: VIEWPORT }}>
            <div style={{ height: VIEWPORT * 3 }}>
              <div className="sticky top-0 flex flex-col overflow-clip" style={{ height: VIEWPORT }}>
                <div className="h-1 bg-hover">
                  <div className="cb-mission-progress h-full bg-accent" />
                </div>
                <div className="flex flex-1 flex-col justify-center gap-4 px-4">
                  <div className="flex flex-col items-center">
                    <span className="text-tau-body text-ink-1">滚动任务控制中心</span>
                    <span className="text-tau-meta text-ink-3">向下滚动，元素按各自区间依次入场</span>
                  </div>
                  <div className="grid grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-3">
                    <Stat
                      className="cb-mission-left"
                      style={{ animationRange: rangeOf("左侧指标") }}
                      value="99%"
                      label="系统加载"
                    />
                    <div
                      className="cb-mission-badge grid size-16 place-items-center rounded-full bg-accent text-ink-inverse shadow-card"
                      style={{ animationRange: rangeOf("中心徽章") }}
                    >
                      <icons.Rocket className="size-7" />
                    </div>
                    <Stat
                      className="cb-mission-right"
                      style={{ animationRange: rangeOf("右侧指标") }}
                      value="12"
                      label="模块就绪"
                    />
                  </div>
                  <div className="flex flex-wrap justify-center gap-2">
                    {CHIPS.map(chip => (
                      <span
                        key={chip.label}
                        className={`cb-mission-chip rounded-full px-3 py-1 text-tau-sm ${chip.className}`}
                        style={{ animationRange: rangeOf(chip.actor) }}
                      >
                        {chip.label}
                      </span>
                    ))}
                  </div>
                  <div className="cb-mission-total flex items-center gap-2">
                    <span className="shrink-0 text-tau-meta text-ink-3">任务总进度</span>
                    <div className="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-hover">
                      <div className="cb-mission-progress h-full rounded-full bg-accent" />
                    </div>
                    <span className="cb-mission-total-value w-9 shrink-0 text-right font-tau-mono text-tau-tiny text-ink-2" />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="flex min-w-0 flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <div className="flex items-baseline justify-between gap-2">
            <span className="text-tau-sm text-ink-3">分镜表</span>
            <span className="font-tau-mono text-tau-sm text-ink-2">--mission-scroll：{Math.round(progress)}%</span>
          </div>
          <div className="relative flex flex-col gap-1.5">
            {ACTORS.map(({ label, range: [start, end] }) => {
              const state = progress < start ? "wait" : progress > end ? "done" : "play";
              return (
                <div key={label} className="grid grid-cols-[72px_minmax(0,1fr)] items-center gap-2">
                  <span
                    className={`truncate text-tau-sm ${state === "play" ? "text-accent-text" : state === "done" ? "text-ink-1" : "text-ink-3"}`}
                  >
                    {label}
                  </span>
                  <div className="relative h-2 rounded-full bg-hover">
                    <div
                      className={`absolute inset-y-0 rounded-full ${state === "wait" ? "bg-press" : "bg-accent"}`}
                      style={{ left: `${start}%`, width: `${end - start}%` }}
                    />
                  </div>
                </div>
              );
            })}
            <div
              className="pointer-events-none absolute -inset-y-1 w-0.5 rounded-full bg-ink-1"
              style={{ left: `calc(80px + (100% - 80px) * ${progress / 100})` }}
            />
          </div>
          <div className="flex justify-between pl-[80px] font-tau-mono text-tau-tiny text-ink-3">
            <span>0%</span>
            <span>50%</span>
            <span>100%</span>
          </div>
          <p className="m-0 text-tau-meta text-ink-3">
            七个元素共用一条滚动时间轴，各自的 animation-range 决定入场时机。
          </p>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <Chip>scroll-timeline: --mission-scroll block</Chip>
        <Chip>animation-timeline: --mission-scroll</Chip>
        <ui.Button
          variant="ghost"
          size="sm"
          icon={icons.ArrowUpToLine}
          className="ml-auto"
          onClick={() => scrollerRef.current?.scrollTo({ top: 0, behavior: "smooth" })}
        >
          回到顶部
        </ui.Button>
      </div>
    </div>
  );
};

