content.content:
const { useEffect, useRef, useState } = React;

const DEFAULT_SCOPED = false;
const VIEWPORT = 260;
const SUBJECT = 96;

const KIT_STYLE = `
  @scope {
    .cb-scope-subject { view-timeline: --card-view block; }
    .cb-scope-effect {
      counter-reset: cb-sda var(--cb-sda-p);
      animation: cb-sda-meter linear both;
      animation-timeline: --card-view;
    }
    .cb-scope-fill {
      transform-origin: left;
      transform: scaleX(calc(var(--cb-sda-p) / 100));
    }
    .cb-scope-value::after { content: counter(cb-sda) "%"; }
  }
  @property --cb-sda-p {
    syntax: "<integer>";
    inherits: true;
    initial-value: 0;
  }
  @keyframes cb-sda-meter {
    from { --cb-sda-p: 0; }
    to { --cb-sda-p: 100; }
  }
`;

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
    {children}
  </code>
);

// DOM 结构里的一行：选择器 + 该元素上与时间轴有关的声明
const TreeRow = ({ indent, name, declaration, muted }) => (
  <div className={`flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1 ${indent ? "pl-5" : ""}`}>
    <span className="font-tau-mono text-tau-sm text-ink-1">{indent ? `└ ${name}` : name}</span>
    <span className={`min-w-0 break-all font-tau-mono text-tau-tiny ${muted ? "text-ink-3" : "text-accent-text"}`}>
      {declaration}
    </span>
  </div>
);

const Component = () => {
  const scrollerRef = useRef(null);
  const [scoped, setScoped] = useState(DEFAULT_SCOPED);
  const [scrollTop, setScrollTop] = useState(0);

  useEffect(() => {
    const scroller = scrollerRef.current;
    const onScroll = () => setScrollTop(scroller.scrollTop);
    scroller.addEventListener("scroll", onScroll, { passive: true });
    return () => scroller.removeEventListener("scroll", onScroll);
  }, []);

  // subject 上方留了一屏空白，scrollTop / (视口高 + 元素高) 就是它的 cover 进度
  const subjectProgress = Math.round(Math.min(1, scrollTop / (VIEWPORT + SUBJECT)) * 100);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{KIT_STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          <div ref={scrollerRef} className="overflow-y-auto" style={{ height: VIEWPORT }}>
            <div className="relative" style={scoped ? { timelineScope: "--card-view" } : undefined}>
              <div className="cb-scope-effect sticky top-0 z-10 flex items-center gap-2 border-b border-line-1 bg-surface px-3 py-2">
                <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">.effect</span>
                <div className="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-hover">
                  <div className={`cb-scope-fill h-full rounded-full ${scoped ? "bg-ok" : "bg-danger"}`} />
                </div>
                <span className="cb-scope-value w-9 shrink-0 text-right font-tau-mono text-tau-tiny text-ink-2" />
              </div>
              <div
                className="flex items-end justify-center pb-4 text-tau-meta text-ink-3"
                style={{ height: VIEWPORT - 40 }}
              >
                向下滚动，让 subject 穿过视口
              </div>
              <div
                className="cb-scope-subject mx-6 grid place-items-center rounded-tau-md border border-accent bg-accent-soft"
                style={{ height: SUBJECT }}
              >
                <span className="font-tau-mono text-tau-body text-accent-text">.subject</span>
              </div>
              <div style={{ height: VIEWPORT }} />
            </div>
          </div>
        </div>

        <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          <div className="flex flex-col gap-1.5">
            <TreeRow
              name=".component"
              declaration={scoped ? "timeline-scope: --card-view" : "未设置 timeline-scope"}
              muted={!scoped}
            />
            <TreeRow indent name=".subject" declaration="view-timeline: --card-view block" />
            <TreeRow indent name=".effect" declaration="animation-timeline: --card-view" />
          </div>
          <div
            className={`flex items-center gap-2 rounded-tau-md px-3 py-2 font-tau-mono text-tau-sm ${
              scoped ? "bg-ok-soft text-ok" : "bg-danger-soft text-danger"
            }`}
          >
            {scoped ? <icons.Link className="size-4 shrink-0" /> : <icons.Unlink className="size-4 shrink-0" />}
            <span>effect</span>
            <icons.ArrowRight className="size-3.5 shrink-0" />
            <span>{scoped ? "subject" : "inactive timeline"}</span>
          </div>
          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
            <dt className="text-ink-3">subject 进度</dt>
            <dd className="m-0 font-tau-mono text-ink-1">{subjectProgress}%</dd>
            <dt className="text-ink-3">effect 进度</dt>
            <dd className="m-0 text-ink-1">{scoped ? "跟随 subject" : "始终为 0%"}</dd>
          </dl>
          <p className="m-0 text-tau-meta text-ink-3">
            {scoped
              ? "timeline-scope 把 --card-view 的可引用范围扩大到 .component 子树。"
              : "effect 不在 subject 的子树里，找不到 --card-view。"}
          </p>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Switch checked={scoped} onCheckedChange={setScoped} label="在 .component 上设置 timeline-scope" />
        <span className="ml-auto">
          <Chip>timeline-scope: {scoped ? "--card-view" : "none"}</Chip>
        </span>
      </div>
    </div>
  );
};

