function resolve(element, name) {
  if (element 自己定义了 name) {
    return element 自己的 timeline;
  }

  if (
    element 对 name 设置了 timeline-scope ||
    element 是 documentElement
  ) {
    return element 子树内最后一个有效的同名 timeline
      ?? inactiveTimeline;
  }

  return resolve(element 的 flat-tree 父元素, name);
}
